import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {
 static void verify(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 public static void main(String[] args)throws Exception{Map<String,byte[]> data=new TreeMap<>();int changed=0;try(ZipFile in=new ZipFile(args[0])){for(var es=in.entries();es.hasMoreElements();){ZipEntry e=es.nextElement();byte[] b=in.getInputStream(e).readAllBytes();if(e.getName().equals("dev/survivorcreator/hearing/DeathPanel.class")||e.getName().equals("dev/survivorcreator/hearing/CreationAudio.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);if(c.name.endsWith("DeathPanel")){for(MethodNode legacy:new ArrayList<>(c.methods))if(legacy.name.equals("render")){legacy.name="renderLegacy24";MethodNode m=new MethodNode(ACC_PUBLIC|ACC_STATIC,"render",legacy.desc,null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new VarInsnNode(ILOAD,2));m.instructions.add(new VarInsnNode(ILOAD,3));m.instructions.add(new VarInsnNode(LLOAD,4));m.instructions.add(new FieldInsnNode(GETSTATIC,c.name,"report","Ldev/survivorcreator/hearing/DeathReport;"));m.instructions.add(new FieldInsnNode(GETSTATIC,c.name,"detail","Lcom/google/gson/JsonObject;"));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/autopsy/Autopsy","render","(Ljava/lang/Object;Ljava/lang/Object;IIJLjava/lang/Object;Ljava/lang/Object;)Z",false));LabelNode fallback=new LabelNode();m.instructions.add(new JumpInsnNode(IFEQ,fallback));m.instructions.add(new InsnNode(RETURN));m.instructions.add(fallback);m.instructions.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new VarInsnNode(ILOAD,2));m.instructions.add(new VarInsnNode(ILOAD,3));m.instructions.add(new VarInsnNode(LLOAD,4));m.instructions.add(new MethodInsnNode(INVOKESTATIC,c.name,"renderLegacy24",legacy.desc,false));m.instructions.add(new InsnNode(RETURN));c.methods.add(m);changed++;}}else{MethodNode m=new MethodNode(ACC_PUBLIC|ACC_STATIC,"zomboid$spawnView","(Lnet/neoforged/neoforge/client/event/ClientTickEvent$Post;)V",null,null);m.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true).visitEnd();m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/autopsy/SpawnView","tick","(Ljava/lang/Object;)V",false));m.instructions.add(new InsnNode(RETURN));c.methods.add(m);changed++;}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();verify(b);}data.put(e.getName(),b);}}try(var fs=Files.walk(Path.of(args[2]))){for(Path p:fs.filter(x->x.toString().endsWith(".class")).toList()){byte[] b=Files.readAllBytes(p);verify(b);data.put(Path.of(args[2]).relativize(p).toString(),b);}}try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:data.entrySet()){out.putNextEntry(new ZipEntry(e.getKey()));out.write(e.getValue());out.closeEntry();}}if(changed!=2)throw new IllegalStateException("Missing UI/spawn hooks");System.out.println("Verified autopsy rendering and first-person spawn hooks");}
}
